<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientClientNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientClientNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withClientName,
 * getClientName/clientName accessors, and isClientNameChanged with/without original.
 */
class TrustedClientClientNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withClientName creates a new instance with the ClientName set
     * from a string value, and getClientName returns the primitive string.
     */
    public function testWithClientNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientNameAccessorUnitTest();

        // Act
        $result = $holder->withClientName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getClientName());
    }
    /**
     * Asserts that withclientName has access to the value object
     * from a string value, and getClientName returns the primitive string.
     */
    public function testWithClientNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientNameAccessorUnitTest();

        // Act
        $result = $holder->withClientName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->clientName()->value());
    }
    public function testChangedClientName(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientNameAccessorUnitTest();
        $original = $holder->withClientName('one');
        $same = $holder->withClientName('one');
        $modified = $holder->withClientName('other');

        // Act
        $unchanged = $holder->isClientNameChanged();
        $withSame = $original->isClientNameChanged($same);
        $withDiferent = $original->isClientNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientClientNameAccessorUnitTest
{
    use TrustedClientClientNameAccessor;
}
